using StrataLint.Scribe;
using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra;

internal sealed class LatticeHalfFockNestedQReadoutDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The three nested fractional products retain one actual labelled Laurent numerator.",
        H("Nested Ordered Q Readouts"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("actual-nested-ordered-readouts"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/LatticeHalfFockNestedQReadout.actual_nested_ordered_readouts"),
                H("All three nested coefficients are extracted from the same actual ternary numerator"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/VertexAlgebra/bakalovkac2004lattice")),
                Blocks(
                    Paragraph(Text("Let J be the actual half-frequency current, A=T_gamma(a) and B=T_delta(b), where a,b are arbitrary original source states. Choose K from the actual finite Laurent carrier theorem. For signed d,r,n, an arbitrary actual tensor input x and complex linear functional phi, take the degree-T slice of the original six-order cleared numerator, where T=L+M+N-d-r-n-3 and L,M,N are the three original clearing orders. The same labelled Laurent polynomial P gives all three nested readouts. All charges, both theta signs and unreduced signed lifts remain in scope.")),
                    Paragraph(Text("The source theta parity and signed lift carry are consequences of correctedField_theta and physicalSlice_mode on the original source carrier, without any theta action on the actual tensor input. For every original a and signed s,n, T_s(theta(a))[n]=(-1)^s T_s(a)[n], since the doubled exponent -2n-s-2 has the same parity as s. Thus T_s((a+(-1)^s theta(a))/2)[n]=T_s(a)[n]; the formula includes both theta projections as s varies. For every signed v, T_(s+2v)(a)[n]=T_s(a)[n+v] by the exact equality of doubled exponents. These identities do not identify a Q product with a collision Taylor readout.")),
                    Paragraph(Text("The first coefficient is Q_r^(gamma+1)(T_(gamma+1)(h_d a),B)[n]x. The second is Q_(d-j)^1(J,Q_(r+j)^gamma(A,B))[n]x. The third is Q_(d+r-j)^gamma(A,T_(delta+1)(h_j b))[n]x, for every signed j. The first and third use the actual current inverse to identify the source current insertion. Their inner cutoffs are respectively vectorFrequencyBound(a)+1 and vectorFrequencyBound(b)+1. The second uses K for its inner source pair. Every outer cutoff is arbitrary.")),
                    Paragraph(Text("finiteQReadout uses the literal finite fractional sum and both complete residue halves. The forward range is max(0,-ord(Bx)-n+ell); the reverse range is max(0,-ord(Ax)). In a nesting, A or B here can be the complete intermediate Q field. Its order is taken before splitting its inner residue. Each inner range is then recomputed on the actual intermediate vector. No two unbounded chamber sums are separated or exchanged.")),
                    Paragraph(Text("nestedLeftReadout and nestedRightReadout retain all four resulting triple words and their signs. rationalTripleReadout reads each word from the supported permutation expansion of P divided by the original clearing polynomial. The third nesting exchanges current and first-source labels in the readout while leaving P and its denominator unchanged. Every summand has total mode index d+r+n; hence its total exponent is -d-r-n-3 and the same slice T applies to every fractional correction, residue offset and j.")),
                    Paragraph(Text("This theorem identifies nested ordered rational coefficients. The separate collision-Taylor theorem below proves the finite fractional coordinate cocycle and the signed two-residue balance of the same actual numerator. Identification of these chart residues with the three complete nested Q readouts remains unproved. Consequently Lambda_tar=0, residual-free DE-L, universal negative first-word transport and all-charge induction remain open. GroundFirst is an independent final lifting base. No target vacuum, positive definiteness, energy eigenstate, or compatibility law is assumed."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("actual-collision-taylor-balance"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/LatticeHalfFockNestedQReadout.actual_collision_taylor_balance"),
                H("The same actual numerator satisfies the finite coordinate cocycle and signed collision balance"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/VertexAlgebra/bakalovkac2004lattice")),
                Blocks(
                    Paragraph(Text("For every D, determinant-unit witness hu, current label i and original source states a,b, choose K from the nested ordered theorem. For every signed gamma,delta,d,r,n, actual tensor x and complex linear functional phi, P is the same finite labelled degree-T slice of the actual numerator, T=L+M+N-d-r-n-3. Here L=vectorFrequencyBound(a)+1, M=vectorFrequencyBound(b)+1 and N=K. The same existential K,P also retain all three actual nested ordered-Q equations, for every outer cutoff and signed j, before the additional chart identities are stated. No numerator exponent is required to be nonnegative.")),
                    Paragraph(Text("Write C(u,v) for the finite sum of P_e times choose(e_0-1/2,u) choose(e_1-gamma/2,v). The left-associated coefficient is the finite sum of P_e times choose(e_0-1/2,u) choose(e_0+e_1-u-(gamma+1)/2,v). The theorem proves that this coefficient equals sum over 0<=j<=v of choose(u+j,u) C(u+j,v-j). This is the coefficient identity under x=h+t for the exact common fractional factor. The proof uses choose_smul_choose and finite Vandermonde; it never divides by a binomial coefficient.")),
                    Paragraph(Text("Set D=L+M+N-d-r-2. The collisionChart is the finite rational sum, over 0<=u<=D, of C(u,D-u) x^(u-M) t^(D-u+r-N) (x-t)^(d-L). The native rational kernel uses integration variable z=x and coefficient-field variable X=t. A negative D gives the empty sum. Its fused residue in x equals the difference of its two supported ordered residues as complete Laurent series in t. Negative powers of both x and x-t use the existing negative_laurent_collision theorem. Nonnegative x powers use the original polynomial collision theorem, and nonnegative diagonal powers use a recurrence from separated rational poles. Rational coefficients in t are pulled through the supported residue maps.")),
                    Paragraph(Text("For every nonnegative integer degree equal to D, the theorem also gives the literal scalar two-residue coefficient identity. For A=u-M, B=D-u+r-N and k=d-L, A+B+k=-2. The fused weight is choose(A,-k-1) when k<0 and zero otherwise. It equals the forward weight chooseSign(k,-B-1) when B<0 minus epsilon(k) times the reverse weight chooseSign(k,-A-1) when A<0. Every inequality is strict at the zero boundary. Both chambers, all integer signs and the complete epsilon(k) factor are retained.")),
                    Paragraph(Text("These are finite chart identities for the actual numerator. sameNumeratorCollisionBridge states the still-unproved identification with the complete nested Q products, using one outer locality order for the first product and independent orders for every intermediate field in the two finite families. Equality of either chart residue with a complete nested Q coefficient has not been established. In particular no complete intermediate cutoff is imposed on an individual ordered half. The binary Taylor readout remains valid, but its integration with the three-field supported extraction, the source theta/lift carry, target interchange, residual-free DE-L and the all-charge first-word consumer remain further obligations. GroundFirst remains a separate final base."))),
                DescribeRole.Theorem))));
}
